let patientName = 'Valued Patient';
let patientPhone = 'Unknown Phone';
let callId = null;

try {
  const vapiData = $('Vapi Post-Call Ingest').first().json;
  const extracted = $('Information Extractor').first()?.json || {};

  // 1. Get structured patient name from LLM extractor, fallback to default
  if (extracted.patient_name && extracted.patient_name.trim() !== '') {
    patientName = extracted.patient_name.trim();
  }

  // 2. Get patient phone from LLM extractor, then Vapi payload metadata, fallback to default
  patientPhone = extracted.patient_phone 
              || vapiData.message?.call?.customer?.number 
              || vapiData.customer?.number 
              || patientPhone;

  callId = vapiData.message?.call?.id || null;
} catch (error) {
  // Safe defaults persist if node context is unlinked during partial manual test runs
}

return [{
  json: {
    patient_name: patientName,
    patient_phone: patientPhone,
    reason: 'Booking not found in database',
    call_id: callId
  }
}];

